import assert from 'node:assert/strict'
import fs from 'node:fs/promises'
import { chromium } from '@playwright/test'

// Generated by publish-editorial-pass.mjs --verify; contains public URLs only.
const articles = JSON.parse(
  await fs.readFile('.tools/editorial-publication.json', 'utf8'),
)
const samples = [
  '05-函数签名重载this与回调.md',
  '01-IoC依赖注入与Bean生命周期.md',
  '03-PostgreSQL基础.md',
  '01-最小Agent Loop实现.md',
  '01-Context Engineering总览.md',
  'AGENT_SOURCE_05_OPENCLAW.md',
  '01-Spring Petclinic.md',
]
const browser = await chromium.launch({
  executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH,
  headless: true,
})
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })
page.setDefaultTimeout(30_000)
const errors = []
page.on('pageerror', (error) => errors.push(error.message))
await fs.mkdir('.tools/editorial-screenshots', { recursive: true })

try {
  for (const name of samples) {
    const article = articles.find((item) => item.file.endsWith(`/${name}`))
    assert(article, `Missing publication record: ${name}`)
    const response = await page.goto(article.url, { waitUntil: 'networkidle' })
    assert.equal(response?.status(), 200, `HTTP response: ${name}`)
    await page.locator('.markdown-body').waitFor()
    const text = await page.locator('.markdown-body').innerText()
    assert(
      text.includes(article.intro.replace(/[`*]/g, '')),
      `Updated introduction missing: ${name}`,
    )
    const headings = await page
      .locator(
        '.markdown-body h2, .markdown-body h3, .markdown-body h4, .markdown-body h5, .markdown-body h6',
      )
      .evaluateAll((elements) => elements.map((element) => `#${element.id}`))
    const links = await page
      .locator('.toc nav a')
      .evaluateAll((elements) =>
        elements.map((element) => element.getAttribute('href')),
      )
    assert.deepEqual(links, headings, `Incomplete or unordered TOC: ${name}`)
    console.log(
      JSON.stringify({
        file: name,
        status: response.status(),
        headings: headings.length,
        updated: true,
      }),
    )
  }

  for (const width of [390, 820, 1280]) {
    await page.setViewportSize({ width, height: 900 })
    await page.reload({ waitUntil: 'networkidle' })
    await page.locator('.markdown-body').waitFor()
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth - window.innerWidth,
    )
    assert(overflow <= 1, `Horizontal overflow at ${width}px: ${overflow}px`)
    await page.screenshot({ path: `.tools/editorial-screenshots/article-${width}.png` })
  }
  assert.deepEqual(errors, [], 'Browser runtime errors')
  console.log('Verified 7 live articles, matching TOCs, and 390/820/1280px layouts')
} finally {
  await browser.close()
}
